#!/usr/bin/env python3
import base64
import json
import os
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

STATE = Path("/var/lib/traffic-surge/priority.json")
STATE_LOCK = threading.RLock()
OPTIONAL_SLOTS = threading.BoundedSemaphore(8)


def load_state():
    document = json.loads(STATE.read_text())
    records = document.get("records", document) if isinstance(document, dict) else {}
    state = {}
    for key, value in records.items():
        if isinstance(value, dict) and "__raw__" in value:
            state[key] = base64.b64decode(value["__raw__"])
        else:
            state[key] = value.encode()
    return state


STATE_DATA = load_state()


def write_state(state):
    document = {
        "version": 1,
        "records": {
            key: {"__raw__": base64.b64encode(value).decode("ascii")}
            for key, value in state.items()
        },
    }
    encoded = (json.dumps(document, sort_keys=True, separators=(",", ":")) + "\n").encode()
    temporary = STATE.with_suffix(".tmp")
    try:
        with temporary.open("wb") as stream:
            stream.write(encoded)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, STATE)
        directory = os.open(STATE.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
    finally:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass


class Handler(BaseHTTPRequestHandler):
    def reply(self, status, body=b""):
        self.send_response(status)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def do_GET(self):
        if self.path == "/health":
            self.reply(200, b"ready")
        elif self.path.startswith("/priority/"):
            key = self.path[len("/priority/"):]
            with STATE_LOCK:
                value = STATE_DATA.get(key)
            if value is None:
                self.reply(404)
            else:
                self.reply(200, value)
        elif self.path.startswith("/optional/"):
            key = self.path[len("/optional/"):]
            if not OPTIONAL_SLOTS.acquire(blocking=False):
                self.reply(503)
                return
            try:
                time.sleep(0.45)
                self.reply(200, ("optional:" + key).encode())
            finally:
                OPTIONAL_SLOTS.release()
        else:
            self.reply(404)

    def do_PUT(self):
        if not self.path.startswith("/priority/"):
            self.reply(404)
            return
        key = self.path[len("/priority/"):]
        try:
            length = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            self.reply(400)
            return
        if length < 0:
            self.reply(400)
            return
        value = self.rfile.read(length)
        if len(value) != length:
            self.reply(400)
            return
        with STATE_LOCK:
            STATE_DATA[key] = value
            write_state(STATE_DATA)
        self.reply(204)

    def log_message(self, *_):
        pass


class Server(ThreadingHTTPServer):
    allow_reuse_address = True
    daemon_threads = True
    request_queue_size = 128


Server(("0.0.0.0", 8080), Handler).serve_forever()

